class GalleryViewer{constructor(e,s){this.id=e,this.images=s,this.init()}init(){document.addEventListener("DOMContentLoaded",(()=>this.setupGallery()))}setupGallery(){const e=document.querySelectorAll(`.open-g[g-id="${this.id}"]`),s=document.querySelector(".g-modal"),t=s.querySelector(".g-content");e.forEach((e=>{e.addEventListener("click",(()=>{this.images.length>0?this.showImages(t,s,0):this.showMessage(t,s,Object.assign(document.createElement("div"),{className:"g-message",innerText:"No hay imágenes"}))}))}))}showImages(e,s,t){e.innerHTML=`\n      <div class="g-img-container">\n        <button class="g-close">&times;</button>\n        <button class="g-prev">&#10094;</button>\n        <img class="g-image" src="${this.images[t]}" loading="lazy"/>\n        <button class="g-next">&#10095;</button>\n      </div>\n    `,this.images.length<=1&&(e.innerHTML=`\n    <div class="g-img-container">\n      <button class="g-close">&times;</button>\n      <img class="g-image" src="${this.images[t]}" loading="lazy"/>\n    </div>\n    `),this.setupGallery(),s.classList.add("active");const i=document.querySelector(".g-close"),a=document.querySelector(".g-prev"),n=document.querySelector(".g-next");i.addEventListener("click",(()=>{this.closeGallery(e,s)})),this.images.length>1&&(a.addEventListener("click",(()=>{this.images.length>0&&(t=(t-1+this.images.length)%this.images.length,e.querySelector(".g-image").src=this.images[t])})),n.addEventListener("click",(()=>{this.images.length>0&&(t=(t+1)%this.images.length,e.querySelector(".g-image").src=this.images[t])})))}showMessage(e,s,t){e.innerHTML="",e.appendChild(t),s.classList.add("active")}closeGallery(e,s){s.classList.remove("active"),e.innerHTML=""}}const GallerySetups=[{id:"kazuto_music_project",images:["assets/projects/kazuto_music/play-preview.webp","assets/projects/kazuto_music/play-preview2.webp","assets/projects/kazuto_music/queue-preview.webp","assets/projects/kazuto_music/commands-preview.webp","assets/projects/kazuto_music/playlist-preview1.webp","assets/projects/kazuto_music/playlist-preview2.webp","assets/projects/kazuto_music/playlist-preview3.webp","assets/projects/kazuto_music/settings-preview.webp","assets/projects/kazuto_music/lang-preview.webp"]}];GallerySetups.forEach((e=>new GalleryViewer(e.id,e.images))),document.querySelectorAll(".open-g").forEach((e=>{GallerySetups.find((s=>s.id==e.getAttribute("g-id")))||e.addEventListener("click",(()=>{const e=document.querySelector(".g-modal"),s=e.querySelector(".g-content");s.innerHTML="";const t=Object.assign(document.createElement("button"),{className:"g-nclose",innerHTML:"&times;"});t.addEventListener("click",(()=>{e.classList.remove("active"),s.innerHTML=""}));[t,Object.assign(document.createElement("div"),{className:"g-message",innerText:"No se encontraron imágenes"})].forEach((e=>s.appendChild(e))),e.classList.add("active")}))}));